// The few filled Ionicons that mean a STATE (picked, starred, on) keep a
// solid form: 'all' fills every shape, 'badge' fills the container and
// draws its mark in white, 'dot' fills only the inner dot.
export const SOLID_IONICONS: Record<string, 'all' | 'badge' | 'dot'> = {
  "checkbox": "badge",
  "checkmark-circle": "badge",
  "close-circle": "badge",
  "heart": "all",
  "radio-button-on": "dot",
  "star": "all",
  "stop": "all",
};
